using System.Text.Json.Nodes;
namespace AetherGrid.Server;
/// <summary>Thermal Dijkstra over a fixed demonstration graph; advisory, not navigation.</summary>
public sealed class Routing(Workflow workflow)
{
 public static double Weight(JsonObject e,double q10,double temp,bool broken,double life){var hours=e.N("distance_km")/Math.Max(5,e.N("base_speed_kmh"));var ambient=e.S("road_type")=="urban"?38:35;var projected=broken?ambient-(ambient-temp)*Math.Exp(-hours/.75):temp;var road=e.S("road_type") switch{"sh"=>1.15,"rural"=>1.3,"urban"=>1.2,_=>1};return hours*Math.Pow(q10,((temp+projected)/2-5)/10)*(1+Math.Max(0,(100-e.N("cellular_coverage_pct",90))/100))*road*(1+e.N("accident_risk")*5)*(1+Math.Max(0,life-.5)*2);}
 public object Plan(JsonObject b){
  var nodes=workflow.Catalog["nodes"]!.AsArray().Select(n=>n!.AsObject()).ToDictionary(n=>n.S("id"));var adjacency=nodes.Keys.ToDictionary(k=>k,_=>new List<JsonObject>());
  foreach(var n in workflow.Catalog["edges"]!.AsArray()){var e=n!.AsObject();adjacency[e.S("from_node")].Add(e);var reverse=e.Copy();reverse["from_node"]=e.S("to_node");reverse["to_node"]=e.S("from_node");adjacency[reverse.S("from_node")].Add(reverse);}
  var start=nodes.Values.MinBy(n=>Workflow.Km(b.N("lat"),b.N("lng"),n.N("lat"),n.N("lng")))!;var end=nodes.Values.MinBy(n=>Workflow.Km(b.N("dest_lat"),b.N("dest_lng"),n.N("lat"),n.N("lng")))!;
  var dist=new Dictionary<string,double>{{start.S("id"),0}};var prev=new Dictionary<string,JsonObject>();var queue=new PriorityQueue<string,(double,string)>();queue.Enqueue(start.S("id"),(0,start.S("id")));var q10=workflow.Profile(b.S("commodity")).Q10;
  while(queue.TryDequeue(out var current,out var priority)){if(priority.Item1>dist[current])continue;foreach(var e in adjacency[current]){var next=e.S("to_node");var cost=dist[current]+Weight(e,q10,b.N("temp_c",12),b.B("reefer_broken"),b.N("life_consumed_pct")/100);if(cost<dist.GetValueOrDefault(next,double.PositiveInfinity)){dist[next]=cost;prev[next]=e;queue.Enqueue(next,(cost,next));}}}
  J.Require(dist.ContainsKey(end.S("id")),"No connected graph path",409);var path=new List<string>{end.S("id")};var edges=new List<JsonObject>();var at=end.S("id");while(at!=start.S("id")){var e=prev[at];edges.Add(e);at=e.S("from_node");path.Add(at);}path.Reverse();var access=Workflow.Km(b.N("lat"),b.N("lng"),start.N("lat"),start.N("lng"))+Workflow.Km(b.N("dest_lat"),b.N("dest_lng"),end.N("lat"),end.N("lng"));var hours=edges.Sum(e=>e.N("distance_km")/Math.Max(5,e.N("base_speed_kmh")))+access/30;
  return new{plan_type="deliver",target_id=end.S("id"),target_name=b.S("destination_name"),target_lat=b.N("dest_lat"),target_lng=b.N("dest_lng"),distance_km=J.R(edges.Sum(e=>e.N("distance_km"))+access),ett_hours=J.R(hours),node_path=path,edge_count=edges.Count,score=dist[end.S("id")],viable_by_heuristic=hours<b.N("rvh_hours"),reason="Advisory thermal Dijkstra; graph and biological assumptions are unvalidated. No dispatch or physical route verified.",advisory_only=true};
 }

 public JsonArray Ranked(JsonObject b,IEnumerable<JsonObject> buyers,IEnumerable<JsonObject> cold){
  Workflow.Coordinates(b.N("lat"),b.N("lng"));Workflow.Coordinates(b.N("dest_lat"),b.N("dest_lng"));J.Require(b.N("life_consumed_pct") is >=0 and <=150&&b.N("temp_c",12) is >=-80 and <=100,"Invalid routing state");
  var nodes=workflow.Catalog["nodes"]!.AsArray().Select(n=>n!.AsObject()).ToDictionary(n=>n.S("id"));
  string Nearest(double lat,double lng)=>nodes.Values.MinBy(n=>Workflow.Km(lat,lng,n.N("lat"),n.N("lng")))!.S("id");
  var adj=nodes.Keys.ToDictionary(k=>k,_=>new List<JsonObject>());
  foreach(var n in workflow.Catalog["edges"]!.AsArray()){var e=n!.AsObject();adj[e.S("from_node")].Add(e);var rev=e.Copy();rev["from_node"]=e.S("to_node");rev["to_node"]=e.S("from_node");adj[rev.S("from_node")].Add(rev);}
  var start=Nearest(b.N("lat"),b.N("lng"));var dist=new Dictionary<string,double>{{start,0}};var prev=new Dictionary<string,string>();var visited=new HashSet<string>();var queue=new PriorityQueue<string,(double,string)>();queue.Enqueue(start,(0,start));var profile=workflow.Profile(b.S("commodity"));var life=b.N("life_consumed_pct")/100;
  while(queue.TryDequeue(out var current,out _)){if(!visited.Add(current))continue;foreach(var e in adj[current]){var next=e.S("to_node");if(visited.Contains(next))continue;var cost=dist[current]+Weight(e,profile.Q10,b.N("temp_c",12),b.B("reefer_broken"),life);if(cost<dist.GetValueOrDefault(next,double.PositiveInfinity)){dist[next]=cost;prev[next]=current;queue.Enqueue(next,(cost,next));}}}
  JsonArray Path(string target){var path=new List<string>{target};while(prev.TryGetValue(target,out var before)){path.Add(before);target=before;}path.Reverse();return new JsonArray(path.Select(x=>(JsonNode?)JsonValue.Create(x)).ToArray());}
  var plans=new List<JsonObject>();
  void Add(string type,string id,string name,double lat,double lng,string nid,double score,double spoil,double speed,string reason){var km=Workflow.Km(b.N("lat"),b.N("lng"),lat,lng);plans.Add(new JsonObject{["plan_type"]=type,["target_id"]=id,["target_name"]=name,["target_lat"]=lat,["target_lng"]=lng,["distance_km"]=J.R(km),["ett_hours"]=J.R(km/speed),["expected_spoilage_pct"]=J.R(spoil),["node_path"]=Path(nid),["edge_count"]=0,["score"]=Math.Round(score,4),["reason"]=reason});}
  var target=Nearest(b.N("dest_lat"),b.N("dest_lng"));
  if(dist.TryGetValue(target,out var d)){var spoil=Math.Min(100,life*100+d/profile.ShelfHoursRef*100);Add("deliver",target,nodes[target].S("name"),b.N("dest_lat"),b.N("dest_lng"),target,d,spoil,45,spoil<100?"Original destination reachable within biological budget":"Will spoil before arrival");}
  void Alternative(IEnumerable<JsonObject> candidates,bool isCold){JsonObject? best=null;string? nid=null;double score=double.PositiveInfinity;foreach(var candidate in candidates){Workflow.Coordinates(candidate.N("lat"),candidate.N("lng"));var n=Nearest(candidate.N("lat"),candidate.N("lng"));if(dist.TryGetValue(n,out var cost)&&cost-(isCold?1:2)<score){best=candidate;nid=n;score=cost-(isCold?1:2);}}if(best is null||isCold&&!b.B("reefer_broken"))return;var km=Workflow.Km(b.N("lat"),b.N("lng"),best.N("lat"),best.N("lng"));Add(isCold?"cold_recharge":"liquidate",best.S("id"),best.S("name"),best.N("lat"),best.N("lng"),nid!,score,isCold?life*100:life*100+km/50*1.2,50,isCold?"Emergency cold-storage: reefer failure, recharge to rescue cargo":"Geo-liquidate to "+best.S("kind")+" within 45 km");}
  Alternative(buyers,false);Alternative(cold,true);
  return new JsonArray(plans.OrderBy(p=>p.N("score")).Select(p=>(JsonNode)p).ToArray());
 }
 public JsonArray Operational(Tx tx,JsonObject b){var rvh=b.N("rvh_hours");var buyers=tx.All("buyer").Where(x=>x.B("pre_authorized")&&x.N("capacity_kg")>=b.N("weight_kg")&&x["accepted_commodities"] is JsonArray cs&&cs.Any(c=>c!.GetValue<string>()==b.S("commodity"))&&Workflow.Km(b.N("lat"),b.N("lng"),x.N("lat"),x.N("lng"))<=Math.Min(80,x.N("service_radius_km"))&&Workflow.Km(b.N("lat"),b.N("lng"),x.N("lat"),x.N("lng"))/30+.25<rvh).ToArray();var cold=workflow.Catalog["nodes"]!.AsArray().Select(n=>n!.AsObject()).Where(n=>n.B("cold")&&Workflow.Km(b.N("lat"),b.N("lng"),n.N("lat"),n.N("lng"))/30+.25<rvh);var plans=Ranked(b,buyers,cold);foreach(var n in plans){var p=n!.AsObject();p["advisory_only"]=true;p["reason"]=p.S("plan_type")=="cold_recharge"?"Cold holding may slow decay; it cannot restore consumed shelf life. Capacity/availability require operator verification.":"Heuristic advisory; eligibility is rechecked at bid. No physical dispatch.";}return plans;}
}
